function ChannelManager({ channel, manage, refresh, error }: { channel: Channel; manage: boolean; refresh: () => Promise<void>; error: (e: unknown) => void }) { const [name, setName] = useState(channel.name), [remove, setRemove] = useState(false); return <div className="channel-manager-wrap"><div className="channel-manager">{channel.kind === 'text' ? <Hash size={18}/> : <Volume2 size={18}/>}<input aria-label={tr('Rename {name}', { name: channel.name })} value={name} disabled={!manage} onChange={e => setName(e.target.value)}/>{manage && <><IconButton title={tr('Save {name}', { name: channel.name })} onClick={() => { void request(`/channels/${channel.id}`, { name }, 'PATCH').then(refresh).catch(error); }}><Check/></IconButton><IconButton title={tr('Delete {name}', { name: channel.name })} danger onClick={() => setRemove(!remove)}><Trash2/></IconButton>{remove && <button className="danger-button" onClick={() => { void request(`/channels/${channel.id}`, { delete: true }, 'PATCH').then(refresh).catch(error); }}>{tr("Confirm delete")}</button>}</>}<IconButton title={tr("Copy channel link")} onClick={() => { void navigator.clipboard.writeText(channelLink(serverUrl() || location.origin, channel.serverId, channel.id)).catch(error); }}><Copy/></IconButton></div><VoicePolicy key={`${channel.id}-${JSON.stringify(channel.requiredTags)}-${channel.locked}-${channel.userLimit}`} channel={channel} refresh={refresh} error={error}/></div>; }
